PROGRAM ST270_PRESSTATION
VAR
    steg    : INT := 0;
    xNed    : BOOL := FALSE;
    xUp     : BOOL := FALSE;
    xHold   : BOOL := FALSE;
    xDone   : BOOL := FALSE;
    xSparr  : BOOL := FALSE;
    trigSaf : F_TRIG;
    tmrHold : TON;
END_VAR

(* ST270_SAF_OK ar sakerhets-PLC:ns fardiga forregning: tvahandsdonet och
   ljusridan. Logiken LAS den och skriver aldrig i den; den upprepar ingen
   samtidighetskontroll och overbygger inget flimmer. Ett avbrott pa fallande
   flank sparrar pressen til manuell aterstart. *)
trigSaf(CLK := ST270_SAF_OK);

IF trigSaf.Q THEN
    xSparr := TRUE;
END_IF;

(* Halltiden 0,80 s borjar nar pressen NATT BOTTENLAGET, alltsa nar
   ST270_PRS_BOTTOM gar hog, aldrig nar nedrorelsen kommenderas. *)
tmrHold(IN := xHold, PT := T#800ms);

IF NOT EMG_OK OR NOT AIR_OK THEN
    xNed := FALSE;
    xUp := FALSE;
    xHold := FALSE;
    xDone := FALSE;
    steg := 0;
ELSE
    CASE steg OF
        0:
            IF ST270_PRT_PRS AND ST270_PRS_TOP AND ST270_SAF_OK
                    AND NOT xSparr THEN
                steg := 1;
            END_IF;
        1:
            xNed := TRUE;
            steg := 2;
        2:
            IF ST270_PRS_BOTTOM THEN
                xNed := FALSE;
                IF ST270_PRS_FORCE >= 40.0 AND ST270_PRS_FORCE <= 80.0 THEN
                    xHold := TRUE;
                    steg := 3;
                ELSE
                    (* Bottenlage utan arbetskraft, eller overkraft over
                       pressens tak 80 kN: pressen kor upp och cykeln
                       avbryts. *)
                    xUp := TRUE;
                    steg := 9;
                END_IF;
            END_IF;
        3:
            IF tmrHold.Q THEN
                xHold := FALSE;
                xUp := TRUE;
                steg := 4;
            END_IF;
        4:
            IF ST270_PRS_TOP THEN
                xUp := FALSE;
                xDone := TRUE;
                steg := 5;
            END_IF;
        5:
            IF NOT ST270_PRT_PRS THEN
                xDone := FALSE;
                steg := 0;
            END_IF;
        9:
            (* Avbruten cykel: pressen kor upp och star sedan stilla. *)
            IF NOT ST270_PRS_TOP THEN
                xUp := TRUE;
            ELSE
                xUp := FALSE;
            END_IF;
    ELSE
        steg := 0;
    END_CASE;
END_IF;

(* En skrivning per utgang, forreglingarna i samma uttryck (F7): nedrorelsen
   bara med sluten sakerhetskrets och utan aterstartssparr, upprorelsen
   aldrig samtidigt som nedrorelsen. *)
ST270_PRS_DOWN := xNed AND ST270_SAF_OK AND EMG_OK AND AIR_OK AND NOT xSparr;
ST270_PRS_UP := xUp AND EMG_OK AND AIR_OK AND NOT xNed;
ST270_CYC_DONE := xDone;
END_PROGRAM

